namespace Nclex.Domain.Entities;

/// <summary>Where a test set comes from (database enum <c>test_set_kind</c>).</summary>
public enum TestSetKind
{
    /// <summary>Curated by the content team and shown to everyone on the track (PRD 5.5).</summary>
    Prebuilt,

    /// <summary>Generated by the custom test builder for one user (F07).</summary>
    Custom,

    /// <summary>Adaptive exam whose items are picked during the attempt (phase 2).</summary>
    Cat,

    /// <summary>Set by an educator for a group (phase 3).</summary>
    Assigned,
}
